commands.code:
mkdir -p ~/dev-opps-lab/infra/local17/output ~/dev-opps-lab/evidence/week-17
cd ~/dev-opps-lab/infra/local17
cat > main.tf <<'EOF'
terraform {
  required_version = ">= 1.10, < 2.0"
  required_providers {
    local = { source = "hashicorp/local", version = "~> 2.5" }
  }
}
variable "filename" {
  type    = string
  default = "notice.txt"
  validation {
    condition     = can(regex("^[a-z0-9-]+[.]txt$", var.filename))
    error_message = "Use a simple lowercase .txt filename, without directories."
  }
}
resource "local_file" "notice" {
  filename        = "${path.module}/output/${var.filename}"
  content         = "Dev Opps: configuration is a reviewable promise.\n"
  file_permission = "0644"
}
output "notice_path" { value = local_file.notice.filename }
EOF
cat > .gitignore <<'EOF'
.terraform/
*.tfstate
*.tfstate.*
*.tfplan
crash.log
EOF
terraform fmt
terraform init
terraform validate
